/**
 * chatDiagnostics — a pure serializer for the "Copy diagnostics" action.
 *
 * The plain transcript (turns + tool I/O) answers "what did the model say?"; this
 * answers "what STATE was this chat in?" — the identity + wiring facts you otherwise
 * have to guess at from screenshots: the chat's own project, the tenant, the project
 * Evermind head (version / mode / learned / queued / last-learned), the learn-gate
 * outcome for the last turn, the agents invited into the chat, and the linked tickets.
 *
 * It is the fix for a whole class of "even after N fixes I can't tell what's wrong"
 * loops: the #1 real cause of "Learning · Connected yet nothing learns" is that the
 * CHAT is bound to a different project (or none) than the panel shows — a fact invisible
 * in the UI but dumped plainly here, with a Signals section that names the likely cause.
 *
 * Pure + host-agnostic (no fetch, no DOM): every surface gathers the data its own way
 * and calls this ONE renderer, so the copied report is identical on web and in VS Code.
 */

/**
 * One execution started against a ticket this chat links. Mirrors the API's
 * `ChatRunRecord` (`application/brain/chatRunHistory.ts`) — kept structural here so the
 * serializer stays pure and host-agnostic, exactly like every other field it renders.
 */
export interface ChatDiagnosticsRun {
  executionId: number;
  taskId: number;
  taskTitle?: string | null;
  agentRef?: string | null;
  agentName?: string | null;
  status: string;
  /** `user:<id>` | `system:lane-auto` | `system:coordinator` | … — WHICH pathway started it. */
  submittedBy: string;
  source?: string;
  /**
   * WHERE it executed: 'container' (real shell + local clone) | 'durable' (shell-LESS,
   * git-API edits) | 'github_actions'. Reported because the two cloud executors differ in
   * what the run was CAPABLE of — only one of them can compile what it wrote — and from
   * inside the transcript they are indistinguishable.
   */
  executor?: string | null;
  /** The on-prem machine this run was delivered to, when it was one. */
  hostId?: number | null;
  hostName?: string | null;
  /** Did the finished run leave a commit / PR / merge / lane move behind? Null = not judged. */
  produced?: boolean | null;
  errorMessage?: string | null;
  startedAt?: string | null;
  completedAt?: string | null;
  createdAt: string;
}

/** The chat's execution history, as gathered. */
export interface ChatDiagnosticsRuns {
  /** How many runnable tickets this chat links — the denominator for "nothing ran". */
  linkedRunnableTickets: number;
  runs: ChatDiagnosticsRun[];
  /** Distinct `submittedBy` labels across those runs. */
  dispatchers: string[];
  /** Distinct executors across those runs ('container' | 'durable' | 'on-prem' | …). */
  executors?: string[];
}

/** The project Evermind head/activity snapshot, as the panel reads it. */
export interface ChatDiagnosticsEvermind {
  version: number;
  mode: string;
  inferenceEnabled?: boolean;
  teacherModel?: string | null;
  /** Merged contributions to date — the panel's "Learned". */
  contributions?: number;
  /** Queued-but-not-yet-merged contributions — the panel's "Queued". */
  pending?: number;
  /** ISO timestamp of the last merge, or null if never — the panel's "Last learned". */
  lastLearnedAt?: string | null;
}

/** One metered resource, mirroring the `/api/consumption` meter snapshot shape. */
export interface ChatDiagnosticsMeter {
  /** 'ai_tokens' | 'ingestion' | 'error_events' | 'outbound_fetches' | 'cloud_runs' */
  key: string;
  /** 'tokens' | 'bytes' | 'events' | 'fetches' | 'runs' */
  unit: string;
  used: number;
  /** Monthly allowance; -1 = unlimited. */
  limit: number;
  unlimited: boolean;
  /** Remaining this month; -1 when unlimited. */
  remaining: number;
  /** 0–100; 0 when unlimited. */
  percentUsed: number;
}

/**
 * WHO the user is to the platform and WHAT they are allowed to spend — the half of
 * "why is this chat behaving like that?" that identity + Evermind state can't answer.
 *
 * The motivating case is a brand-new signup: free plan, no card, a small token
 * allowance and no premium/frontier entitlement. From the outside that looks
 * indistinguishable from a broken install ("it picked a weak model", "it stopped
 * answering") — so the report states the plan, the billing status, the month-to-date
 * meters, and the model entitlement explicitly, and the Signals section names the
 * consequence rather than leaving the reader to infer it.
 */
export interface ChatDiagnosticsAccount {
  /** Effective plan key ('free' | 'pro' | …) as the API resolves it. */
  plan?: string | null;
  /** Billing status ('none' = no payment method on file, 'trialing', 'active', …). */
  billingStatus?: string | null;
  /** Current metering period — when the allowances reset. */
  periodStart?: string | null;
  resetsAt?: string | null;
  /** Month-to-date usage vs allowance for every metered resource. */
  meters?: ChatDiagnosticsMeter[];
  /** The model in force for this chat (absent ⇒ the gateway routes per turn). */
  model?: string | null;
  /** Which purse funds `model`: 'byo:<vendor>' | 'plan' | 'premium' | 'auto'. */
  modelFunding?: string | null;
  /** Whether the plan entitles the tenant to premium/frontier models. */
  canUsePremiumModels?: boolean;
  /**
   * Whether the plan covers the CONTAINER execution surface — a real shell and a local
   * clone. Free workspaces run on the durable (serverless) surface, which is free
   * Cloudflare infrastructure and provably cannot run a build, and a cloud agent
   * explicitly set to `container` is DEMOTED at dispatch rather than refused.
   *
   * Stated explicitly because that demotion is correct, cheap and completely invisible:
   * a free workspace whose agent "ran fine" and produced a diff nothing compiled reads
   * exactly like a paid one that ran the full toolchain.
   */
  containerRuntime?: boolean;
  /** How many models the plan pool currently offers. */
  planModelCount?: number;
  /** Connected bring-your-own provider keys (empty ⇒ every turn is plan-funded). */
  byoProviders?: string[];
  /** Client build + gateway it is talking to, so a report pins the exact surface. */
  extensionVersion?: string | null;
  baseUrl?: string | null;
}

/**
 * WHICH purse funds a model, as a machine key: `auto` (no pin — the gateway routes per
 * turn), `evermind` (the project's own learned head), `byo:<vendor>` (the tenant's own
 * connected account), `plan` (in the plan pool, included), or `premium` (metered at
 * cost + per-request fee).
 *
 * ONE decision, two consumers: the chat header renders a localized sentence from it and
 * the diagnostics report records it. Kept here (not in a UI file) so the sentence a user
 * READS and the key a support report SHOWS can never disagree.
 */
export function classifyModelFunding(
  model: string | null | undefined,
  surface: { data?: Array<{ id?: string }>; byo?: { models?: Array<{ id?: string; vendor?: string }> } } | null | undefined,
): string {
  if (!model) return 'auto';
  // A `project_evermind:<id>` pin is a plan FEATURE — the gateway expands it to the
  // project's current learned head — not a catalog model. It is in no pool, so the
  // fall-through below used to call it `premium`, which on a free plan raised a
  // "premium model, plan not entitled" warning about a model the user never picked
  // and the gateway serves happily.
  if (model.startsWith(PROJECT_EVERMIND_MODEL_PREFIX)) return 'evermind';
  const byo = (surface?.byo?.models ?? []).find((m) => m.id === model);
  if (byo?.vendor) return `byo:${byo.vendor}`;
  if ((surface?.data ?? []).some((m) => m.id === model)) return 'plan';
  return 'premium';
}

import { DEFAULT_TOOL_LIMIT } from './selectTools';
import { PROJECT_EVERMIND_MODEL_PREFIX } from './modelChoice';

/** Everything the diagnostics block needs — already gathered by the host (pure in). */
export interface ChatDiagnosticsData {
  surface?: string;
  chatId?: number | null;
  chatTitle?: string | null;
  /** 'shared' | 'locked' — who can see the chat. */
  chatVisibility?: string | null;
  /**
   * The chat's MODE — 'chat' (answer the question) or 'work' (file it, staff it, run it).
   *
   * Reported because it decides what the run was OBLIGED to do, and therefore what counts
   * as a failure: "it made a plan and stopped" is the correct behaviour in chat mode and a
   * broken run in work mode. A report that omits it makes those two indistinguishable.
   */
  mode?: string | null;
  /** The chat's OWN project (what the learn gate keys on), or null when unattached. */
  projectId?: number | null;
  projectName?: string | null;
  /**
   * The project the surrounding UI/panel currently has SELECTED — `null` when nothing is
   * selected. Always reported (never conditionally omitted): "no project is selected" and
   * "a project IS selected but the chat never adopted it" have opposite causes and
   * opposite fixes, and a report that prints only the chat's project renders them
   * identically as `Chat's project: none`. Reading that ambiguity the wrong way once cost
   * a wrong revert.
   */
  selectedProjectId?: number | null;
  /** Display name for {@link selectedProjectId}, when the host holds one. */
  selectedProjectName?: string | null;
  tenantId?: number | string | null;
  userId?: string | null;
  /** The project Evermind head for the CHAT's project (not the selected one). */
  evermind?: ChatDiagnosticsEvermind | null;
  /** The server learn-gate outcome for the most recent assistant turn, if known. */
  lastLearn?: { learned: boolean; version: number; reason?: string | null } | null;
  /**
   * The agents invited into this chat.
   *
   * `name` is optional only because a client can be talking to an API that predates it;
   * where it is present it is what gets printed. It used to be absent entirely, and the
   * report rendered the raw `agentRef` — so a chat staffed with Bob, John and the
   * Manager copied out as three uuids, and the one question the line exists to answer
   * ("who is on this?") could not be answered from the report at all.
   */
  agents?: Array<{ agentRef: string; role: string; name?: string; builtinKind?: string | null }>;
  /**
   * What has actually RUN for this chat — the pathway half of the report.
   *
   * Invited agents and linked tickets describe INTENT; this describes EXECUTION, and
   * the gap between them is the single most common thing a reader is trying to see. A
   * chat with agents, tickets and no runs has a staffing failure; the same chat with
   * runs that all failed has a runtime one; the same chat with runs started by
   * `system:lane-auto` was never driven from the conversation. None of those were
   * distinguishable before this section existed.
   *
   * Absent means NOT GATHERED (an older surface, a failed read) and is reported as such
   * — never as "nothing ran", which is a different and much stronger claim.
   */
  runs?: ChatDiagnosticsRuns | null;
  tickets?: Array<{ kind: string; ref: string; label?: string; linkType?: string; status?: string }>;
  /** Plan, quota and model entitlement for the signed-in tenant (see the interface). */
  account?: ChatDiagnosticsAccount | null;
  /**
   * How many tools the model could actually call, and why not more. Without this
   * a tool-less Brain ("I don't have that data", zero tool calls) is
   * indistinguishable from a model that simply chose not to call anything — the
   * exact ambiguity that made a silent MCP-catalog failure impossible to diagnose.
   *
   * `advertisedMin`/`advertisedLastTurn` are the OBSERVED per-turn numbers, read off
   * the run's trace (`toolExposureInTrace`). They exist because this line used to
   * render the per-turn CEILING (`up to 64 advertised`) while the Diagnostics block
   * directly below it rendered the real measured range off the same run — two lines
   * in one report answering the same question differently, and the ceiling was the
   * one that was always wrong for the turn that actually failed.
   */
  tools?: {
    count: number;
    error?: string | null;
    loading?: boolean;
    /** Fewest tools advertised on any measured turn; null when no turn was measured. */
    advertisedMin?: number | null;
    /** Tools advertised on the LAST measured turn; null when no turn was measured. */
    advertisedLastTurn?: number | null;
  } | null;
  /**
   * Which BUILD produced this capture. Without it a dump taken minutes before a
   * deploy is indistinguishable from one taken after, so a fixed bug reads as
   * unfixed — which is exactly what happened while debugging chat #71.
   */
  versions?: {
    ui?: string | null;
    api?: string | null;
    /**
     * Short SOURCE HASH of the client build.
     *
     * A version names a RELEASE, not an ARTIFACT: a client can be rebuilt and
     * redistributed under the same version with different code, at which point `ui`
     * alone makes a fixed bug read as unfixed. On 2026-07-25 exactly that happened —
     * two `2026.7.104` VSIXes, one with an agent-stall recovery fix and one without,
     * and the report said `UI 2026.7.104` for both. This is the field that separates
     * them; `"dev"` means the surface was not running a packaged artifact at all.
     */
    uiBuildId?: string | null;
    /** When the client artifact was built, so two builds of the same source are orderable. */
    uiBuiltAt?: string | null;
    /** The WEBVIEW bundle's own source hash, where the surface has one. See below. */
    webviewBuildId?: string | null;
    webviewBuiltAt?: string | null;
    /** One line on whether this machine can run POSIX shell scripts — the fact that
     *  decides whether the `git_sync_latest` / `git_undo` / `git_redo` tools work at
     *  all, and which used to surface only as a raw `cmd.exe` error inside one tool
     *  result that named neither the cause nor anything to check. */
    posixShell?: string | null;
  } | null;
}

function fmtProject(id: number | null | undefined, name?: string | null): string {
  if (id == null) return 'none';
  return name ? `${name} (#${id})` : `#${id}`;
}

/** Human label per meter key — unknown keys fall back to the raw key. */
const METER_LABEL: Record<string, string> = {
  ai_tokens: 'AI tokens',
  ingestion: 'Data ingested',
  error_events: 'Error events',
  outbound_fetches: 'Web fetches',
  cloud_runs: 'Cloud runs',
};

/** Render a meter amount in its own unit (bytes get scaled; everything else counts). */
function fmtMeterValue(value: number, unit: string): string {
  if (value < 0) return '∞';
  if (unit !== 'bytes') return value.toLocaleString('en-US');
  if (value < 1024) return `${value} B`;
  const units = ['KB', 'MB', 'GB', 'TB'];
  let v = value / 1024;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) { v /= 1024; i++; }
  return `${v >= 10 ? Math.round(v) : Math.round(v * 10) / 10} ${units[i]}`;
}

/** "12,345 / 250,000 tokens (5%) · 237,655 left" — or "… (unlimited)". */
function fmtMeter(m: ChatDiagnosticsMeter): string {
  const label = METER_LABEL[m.key] ?? m.key;
  if (m.unlimited) return `${label}: ${fmtMeterValue(m.used, m.unit)} used (unlimited)`;
  return `${label}: ${fmtMeterValue(m.used, m.unit)} / ${fmtMeterValue(m.limit, m.unit)}`
    + ` (${m.percentUsed}%) · ${fmtMeterValue(m.remaining, m.unit)} left`;
}

/** The token meter is the one that actually stops a chat mid-turn (gateway 429). */
function tokenMeter(a: ChatDiagnosticsAccount | null | undefined): ChatDiagnosticsMeter | undefined {
  return (a?.meters ?? []).find((m) => m.key === 'ai_tokens');
}

/** How close a metered allowance is to stopping turns. */
export type AllowanceState = 'ok' | 'warn' | 'exhausted';

/**
 * Classify a token allowance. THE single definition of the thresholds — the
 * diagnostics signals below and any host banner must agree on when to warn, or a
 * user gets a scary banner and a calm report (or vice versa).
 *
 * Takes the structural meter shape, so hosts can pass their own
 * `/api/consumption` snapshot meter without converting it.
 *
 * `unlimited` is authoritative: a tenant the gateway does not cap must never be
 * told it is out of tokens, however large `used` grows.
 */
export function allowanceState(
  meter: { unlimited: boolean; remaining: number; percentUsed: number } | null | undefined,
): AllowanceState {
  if (!meter || meter.unlimited) return 'ok';
  if (meter.remaining <= 0) return 'exhausted';
  return meter.percentUsed >= 80 ? 'warn' : 'ok';
}

/**
 * Compute the actionable "why isn't this working?" signals from the raw facts, so the
 * report NAMES the likely cause instead of leaving the reader to correlate numbers.
 * Ordered most-actionable first. Returns [] when nothing is obviously wrong.
 */
function diagnosticsSignals(d: ChatDiagnosticsData): string[] {
  const out: string[] = [];
  const ev = d.evermind;

  // #1 real cause: the chat isn't bound to a project (the learn gate keys on the
  // CHAT's projectId, not the panel's selected project).
  if (d.projectId == null || d.lastLearn?.reason === 'not-attached') {
    // Two DIFFERENT faults present as one line unless the selected project is named:
    // nothing to adopt (the user has no project selected at all) vs. a broken adopt (a
    // project IS selected and the chat still came up unattached). Branch on it, so the
    // reader is pointed at the right fix instead of guessing between them.
    const unattached =
      "⚠️ Chat is NOT attached to a project (chat.projectId is null). The learn gate keys on the CHAT's project, so this chat contributes NOTHING to any Evermind — even though the panel shows the selected project as connected.";
    if (d.selectedProjectId == null) {
      out.push(
        `${unattached} No project is selected in the sidebar either, so there was nothing for the chat to adopt — SELECT a project, then re-open the chat. (Not an adopt bug.)`,
      );
    } else {
      out.push(
        `${unattached} A project IS selected (${fmtProject(d.selectedProjectId, d.selectedProjectName)}) and the chat still came up unattached, so the ADOPT path is the fault, not the selection — investigate the self-heal that binds an open chat to the active project.`,
      );
    }
  } else if (d.selectedProjectId != null && d.selectedProjectId !== d.projectId) {
    out.push(
      `⚠️ Chat's project (#${d.projectId}) differs from the panel's selected project (#${d.selectedProjectId}). The Evermind panel reflects the SELECTED project; this chat feeds project #${d.projectId}. They are different models — compare the versions below.`,
    );
  }

  if (ev && ev.version < 1) {
    out.push(
      `⚠️ The chat's project Evermind is UNSEEDED (v0). Until a base model is seeded (version ≥ 1) the gate returns "not-seeded" and no turn contributes. This is why a learn step can report v0.`,
    );
  }
  if (ev && ev.version >= 1 && ev.mode !== 'connected') {
    out.push(`⚠️ The chat's project Evermind is "${ev.mode}" (not connected) — read-only, so turns don't contribute.`);
  }
  // The gate reports the head it EVALUATED, and the contribution is queued behind it — so
  // once that learn lands the head is AHEAD of the reported version. That is the learn
  // arriving, not a fault (it fired on every healthy learning chat: "reported v22 · head
  // v23"). Only a head BEHIND the learn step is impossible for one head, since a queued
  // learn only ever moves it forward.
  if (d.lastLearn && d.lastLearn.learned && ev && ev.version >= 1 && ev.version < d.lastLearn.version) {
    out.push(
      `⚠️ Last turn's learn step evaluated v${d.lastLearn.version} but the chat's project head is v${ev.version} — BEHIND it. A queued learn only moves a head forward, so the learn step and the panel are resolving DIFFERENT projects/heads.`,
    );
  }
  const agentCount = d.agents?.length ?? 0;
  if (agentCount === 0) {
    out.push('ℹ️ No agents are invited into this chat (chats.list_agents is empty), so dispatched agents post nothing back here.');
  }

  // THE STAFFING GAP. Agents were invited, tickets were linked, and nothing ever ran —
  // which from inside the transcript is indistinguishable from a chat whose agents are
  // working on it. This is the signal that makes chat #103 legible on the first read:
  // three agents present, seven tickets linked, every code change made by the local
  // session, and no line anywhere saying so.
  const runs = d.runs;
  if (runs && agentCount > 0 && runs.linkedRunnableTickets > 0 && runs.runs.length === 0) {
    const names = (d.agents ?? []).map((a) => a.name?.trim() || a.agentRef).join(', ');
    out.push(
      `⚠️ ${agentCount} agent(s) are in this chat (${names}) and ZERO runs have ever been started against its ${runs.linkedRunnableTickets} runnable ticket(s).`
        + ' The work was filed and staffed on paper; nobody was dispatched. Anything that got done was done by this session itself.'
        + ' Start one with the ▶ control on a linked ticket, or ask in-chat for the agent to be dispatched.',
    );
  }
  // Runs exist but none came from a person in this conversation — the work is moving,
  // just not because anyone asked here. Worth saying, because "it is running" and "it is
  // running for an unrelated reason" lead to different next actions.
  if (runs && runs.runs.length > 0 && !runs.dispatchers.some((dsp) => dsp.startsWith('user:'))) {
    out.push(
      `ℹ️ Every run on this chat's tickets was started by ${runs.dispatchers.join(', ')} — none by a person pressing Run. This conversation has not dispatched anything itself.`,
    );
  }
  // WHERE the runs could not build. 'durable' is not a smaller container — it has no
  // shell at all, so a run on it edits over the git API and provably never compiled,
  // type-checked or tested what it wrote. From the transcript that is invisible: the run
  // is green, the diff looks plausible, and the first person to find out is whoever pulls
  // the branch. On a free workspace this is not a fault, it is the plan; the report says
  // which of the two it is so the reader does not go looking for a broken container.
  const ran = runs?.runs ?? [];
  if (ran.length > 0) {
    const shellless = ran.filter((r) => executorHasShell(r.executor) === false);
    if (shellless.length === ran.length) {
      const why = d.account?.containerRuntime === false
        ? " This workspace's plan does not include the container surface, so every cloud run is routed there by design — upgrade, or run the work in the editor/on-prem where there IS a shell."
        : " The container surface was not used — either no agent here is set to it, or no container was live and the run was demoted. Check the agent's runtime surface.";
      out.push(
        `⚠️ All ${ran.length} run(s) on this chat executed on the DURABLE surface, which has no shell: none of them could build, type-check or test the code they wrote.${why}`,
      );
    } else if (shellless.length > 0) {
      out.push(
        `ℹ️ ${shellless.length} of ${ran.length} run(s) executed on the shell-less durable surface and could not build or test their own output (runs ${shellless.slice(0, 5).map((r) => `#${r.executionId}`).join(', ')}).`,
      );
    }
    const unknown = ran.filter((r) => r.executor == null && r.hostId == null);
    if (unknown.length === ran.length) {
      out.push(
        `ℹ️ No run on this chat recorded WHERE it executed. These predate the executor stamp, so "did it have a shell?" is unanswerable from here — read the runs' own tool audit.`,
      );
    }
  }
  // Completed runs that left nothing behind. The status says success; `produced` says
  // the branch, the PR and the lane are all untouched. Counting only FAILED runs is how
  // a board reached thousands of green executions against three finished tickets.
  const hollow = (runs?.runs ?? []).filter((r) => r.produced === false && r.status === 'completed');
  if (hollow.length > 0) {
    out.push(
      `⚠️ ${hollow.length} run(s) on this chat COMPLETED without producing anything — no commit, PR, merge or lane move (runs ${hollow.slice(0, 5).map((r) => `#${r.executionId}`).join(', ')}). A green run that shipped nothing is not progress; read those runs' output before dispatching the same work again.`,
    );
  }

  // Tool availability outranks most other causes: with no tools the model CANNOT
  // fetch anything, so every data question ends in "I don't have that" or an
  // announced-but-never-made call, with zero tool calls in the trace.
  const tools = d.tools;
  if (tools && !tools.loading) {
    if (tools.error) {
      out.push(
        `⚠️ The MCP tool catalog FAILED to load (${tools.error}), so the Brain has ${tools.count} tools and cannot fetch project data. Turns will say "I don't have that data" or announce a tool call and stop — with 0 tool calls in the trace. This is a wiring fault, not a model fault.`,
      );
    } else if (tools.count === 0) {
      out.push(
        '⚠️ The model has ZERO tools registered, so it cannot read tasks, projects, or any platform data — every data question can only be answered from the prompt. Expect "I don\'t have that data" and 0 tool calls. Check that McpExtensionsBridge is mounted and `/llm/v1/mcp/tools` returns a catalog.',
      );
    } else if (tools.advertisedMin === 0) {
      // A full registry and a turn that was handed NOTHING is the failure a ceiling
      // could never show: the catalog reads healthy, the model reads uncooperative,
      // and the relevance selection is the thing that actually broke.
      out.push(
        `⚠️ A turn in this run was advertised ZERO tools even though ${tools.count} are registered — the per-turn relevance selection, not the catalog, is what left the model empty-handed. Any "I don't have that data" answer on that turn is a selection fault, not a model fault.`,
      );
    }
  }

  // Account signals — the "it's not broken, you're on the free tier" class of cause.
  // A brand-new signup hits all of these at once, and every one of them presents as a
  // capability bug (weak model, refused request, turn that stops) unless it is named.
  const acct = d.account;
  const tokens = tokenMeter(acct);
  if (acct) {
    const free = acct.plan === 'free';
    const noCard = acct.billingStatus === 'none' || acct.billingStatus == null;
    if (free && noCard) {
      out.push(
        'ℹ️ Free plan with NO payment method on file. Expect the smaller monthly token allowance, no premium/frontier models, and turns funded by the shared free pool — none of this is a fault. Adding a card (or connecting your own provider account) lifts all three.',
      );
    } else if (free) {
      out.push('ℹ️ Free plan — premium/frontier models are not entitled and the monthly token allowance is the free tier\'s.');
    }
    if (acct.billingStatus === 'past_due') {
      out.push('⚠️ Billing status is past_due — plan entitlements may be suspended until payment succeeds, which reads as sudden model/quota downgrade.');
    }
    const tokenState = allowanceState(tokens);
    if (tokens && tokenState === 'exhausted') {
      out.push(
        `⚠️ AI token allowance is EXHAUSTED (${tokens.used.toLocaleString('en-US')} / ${tokens.limit.toLocaleString('en-US')} this period). The gateway returns 429 \`plan_token_limit_exceeded\`, so turns fail or stop mid-answer until ${acct.resetsAt ?? 'the period resets'}.`,
      );
    } else if (tokens && tokenState === 'warn') {
      out.push(
        `⚠️ AI token allowance is ${tokens.percentUsed}% used (${tokens.remaining.toLocaleString('en-US')} left, resets ${acct.resetsAt ?? 'at period end'}). Long turns may be cut off by the cap before the model finishes.`,
      );
    }
    if (acct.modelFunding === 'premium' && acct.canUsePremiumModels === false) {
      out.push(
        `⚠️ Model "${acct.model}" is a premium/metered model but this plan is NOT entitled to premium models — the gateway rejects it (402) or falls back to the plan pool, which is why answers look weaker than the picked model implies.`,
      );
    }
    if ((acct.byoProviders?.length ?? 0) === 0 && free) {
      out.push('ℹ️ No bring-your-own provider accounts connected, so every turn spends the plan allowance above. Connecting your own Claude/OpenAI account makes turns $0 against the plan.');
    }
  }
  return out;
}

/** How many runs the report prints in full before it summarises the rest. */
const MAX_RUNS_LISTED = 10;

/**
 * Plain-English gloss for a `submitted_by` label — WHICH pathway started a run.
 *
 * The raw label is kept beside the gloss, never replaced by it: `system:lane-auto` and
 * `user:22c5fd96…` are the facts, and a reader who knows the vocabulary should not have
 * to trust a translation. The gloss is there for the reader who does not.
 */
function dispatcherGloss(submittedBy: string): string {
  if (submittedBy.startsWith('user:')) return 'a human pressed Run';
  if (submittedBy.startsWith('system:lane-auto')) return 'board autonomy, not this conversation';
  if (submittedBy.startsWith('system:coordinator')) return "the manager's coordination pass";
  if (submittedBy.startsWith('manager:')) return 'the manager';
  if (submittedBy.includes('lane-approver')) return 'a lane approver';
  return 'unrecognised dispatcher';
}

/**
 * WHERE a run executed, in the terms that decide what it could do. The distinction the
 * gloss exists for is capability, not hosting: 'durable' is not a smaller container, it
 * is a surface with no shell at all.
 */
function executorGloss(executor: string | null | undefined): string {
  if (executor === 'on-prem') return "on-prem machine (real shell, the machine's own clone)";
  if (executor === 'container') return 'container (real shell + local clone — can build, type-check and test)';
  if (executor === 'durable') return 'durable (serverless, NO shell — edits over the git API; cannot build or test)';
  if (executor === 'github_actions') return "GitHub Actions (the repo's own runners)";
  return 'executor not recorded';
}

/** Could a run on this executor compile what it wrote? `false` only when we KNOW it could not. */
function executorHasShell(executor: string | null | undefined): boolean | null {
  if (executor === 'durable') return false;
  if (executor === 'container' || executor === 'on-prem' || executor === 'github_actions') return true;
  return null;
}

/** `2026-09-21T03:45:34.121Z` → `2026-09-21 03:45` — a timestamp a person can scan. */
function shortTime(iso: string | null | undefined): string {
  if (!iso) return '—';
  return iso.length >= 16 ? `${iso.slice(0, 10)} ${iso.slice(11, 16)}` : iso;
}

/**
 * The EXECUTION HISTORY section: what actually ran for this chat, and who started it.
 *
 * Three outcomes, and they are deliberately worded so they cannot be confused:
 *  - NOT GATHERED   — the surface did not read it. Says so; claims nothing.
 *  - nothing to run — the chat links no runnable ticket, so an empty history is
 *                     arithmetic rather than evidence.
 *  - zero runs      — the chat HAS runnable tickets and none was ever dispatched. This
 *                     is the finding, and it is the one a report could not state before:
 *                     the transcript of a chat whose work was done by the local session
 *                     is indistinguishable from one whose agents are working on it.
 */
function runHistoryLines(runs: ChatDiagnosticsRuns | null | undefined): string[] {
  if (!runs) {
    return ['- Execution history: not gathered (this surface did not read the chat\'s runs — absent is NOT the same as "nothing ran")'];
  }
  if (runs.linkedRunnableTickets === 0) {
    return ['- Execution history: no runnable ticket (task/epic/gap) is linked to this chat, so there is nothing here that could have been run.'];
  }
  if (runs.runs.length === 0) {
    return [
      `- Execution history: ZERO runs against ${runs.linkedRunnableTickets} linked runnable ticket(s).`
        + ' No cloud agent has ever been dispatched for this chat — any code that changed was changed by the session itself.',
    ];
  }
  const out: string[] = [];
  out.push(
    `- Execution history (${runs.runs.length} run(s) over ${runs.linkedRunnableTickets} linked runnable ticket(s), newest first)`
      + ` · started by: ${runs.dispatchers.map((dsp) => `${dsp} (${dispatcherGloss(dsp)})`).join(', ')}`,
  );
  const executors = runs.executors ?? [];
  if (executors.length > 0) {
    out.push(`  - ran on: ${executors.map(executorGloss).join('; ')}`);
  }
  for (const run of runs.runs.slice(0, MAX_RUNS_LISTED)) {
    const who = run.agentName?.trim() || run.agentRef || 'no agent recorded';
    const ticket = `#${run.taskId}${run.taskTitle ? ` "${run.taskTitle}"` : ''}`;
    // `produced` is the run's own verdict on whether it left anything behind. A COMPLETED
    // run that produced nothing is the failure mode the autonomy breaker exists for, and
    // it reads as success everywhere that only prints the status.
    const produced = run.produced === true ? ' · produced output'
      : run.produced === false ? ' · produced NOTHING'
      : '';
    const failed = run.errorMessage ? ` · ${run.errorMessage}` : '';
    const where = run.hostName
      ? ` · on on-prem "${run.hostName}"`
      : run.executor ? ` · on ${run.executor}` : ' · on ? (executor not recorded)';
    out.push(
      `  - run #${run.executionId} · ${who} · ${ticket} · ${run.status}${produced}${where}`
        + ` · by ${run.submittedBy}${run.source ? ` via ${run.source}` : ''}`
        + ` · ${shortTime(run.createdAt)}${run.completedAt ? ` → ${shortTime(run.completedAt)}` : ''}${failed}`,
    );
  }
  if (runs.runs.length > MAX_RUNS_LISTED) {
    out.push(`  - …and ${runs.runs.length - MAX_RUNS_LISTED} earlier run(s) not listed.`);
  }
  return out;
}

/**
 * The per-turn half of the tool line: what the model was ACTUALLY handed, never a
 * ceiling derived from the registry size.
 *
 * Three states, deliberately distinct:
 *  - measured (a run has advertised tools)      → "40–64 advertised per turn (measured)"
 *  - unmeasured but the registry exceeds the cap → says the selection is capped and NOT
 *    yet measured, so nobody reads a bound as an observation
 *  - registry already under the cap              → nothing; every tool goes every turn
 */
function fmtAdvertised(tools: NonNullable<ChatDiagnosticsData['tools']>): string {
  const last = tools.advertisedLastTurn;
  const min = tools.advertisedMin;
  if (last != null) {
    const range = min != null && min !== last ? `${min}–${last}` : `${last}`;
    return ` · ${range} advertised per turn (measured)${min === 0 ? ' · ⚠ a turn was offered NONE' : ''}`;
  }
  if (tools.count > DEFAULT_TOOL_LIMIT) {
    return ` · per-turn selection capped at ${DEFAULT_TOOL_LIMIT}, not yet measured (no turn in this run advertised tools)`;
  }
  return '';
}

/**
 * Render the diagnostics block as Markdown lines (no trailing blank line). Every field
 * is best-effort: an absent value is shown as "unknown"/"none" rather than omitted, so
 * the reader can tell "not gathered" from "genuinely empty".
 */
export function formatChatDiagnostics(d: ChatDiagnosticsData): string[] {
  const lines: string[] = ['## Chat diagnostics'];
  // Named as the CONVERSATION's runtime, not just "surface". The report now also states
  // where each dispatched RUN executed (the Execution history's `ran on:` line), and the
  // two are different machines answering different questions: this one is where the chat
  // turn itself ran, which is the browser on the web and the extension host in the VSIX.
  if (d.surface) lines.push(`- Surface: ${d.surface} (where this CONVERSATION runs; where each dispatched RUN ran is under Execution history)`);
  // FIRST, deliberately: every other number below is only meaningful once you know
  // which build produced them.
  if (d.versions && (d.versions.ui || d.versions.api || d.versions.uiBuildId)) {
    // The build id rides the UI version, never a separate line: they answer one
    // question ("which client produced this?") and split lines get quoted apart.
    const buildId = d.versions.uiBuildId;
    // Named CLIENT, not "UI". The version and hash are the EXTENSION HOST's — the half
    // that runs the tools — and calling it "UI" invited the reading that it described
    // the panel instead, which is exactly how a report of a tool failure could not be
    // matched against the build that fixed it.
    const client = `${d.versions.ui ?? 'unknown'}${buildId ? `+${buildId}` : ''}`
      + (d.versions.uiBuiltAt && d.versions.uiBuiltAt !== 'dev' ? ` (built ${d.versions.uiBuiltAt})` : '');
    lines.push(`- Versions: client ${client} · API ${d.versions.api ?? 'unknown'}`);
    if (buildId === 'dev') {
      lines.push(
        '  - ⚠️ Client build id is "dev" — this capture did NOT come from a packaged build, so its behaviour may not match any released artifact.',
      );
    } else if (d.versions.ui && !buildId) {
      lines.push(
        '  - ⚠️ No client build id — this client does not stamp one, so a rebuild carrying the SAME version is indistinguishable from the build it replaced. "Is the fix in?" cannot be answered from this report.',
      );
    }
    // The two halves, stated separately. A surface that bundles its panel with its host
    // ships them at one age — but only SAYING so makes "the reported version describes
    // the half that was not running the code" a claim a reader can check.
    const webviewId = d.versions.webviewBuildId;
    if (webviewId) {
      const built = d.versions.webviewBuiltAt && d.versions.webviewBuiltAt !== 'dev'
        ? ` (built ${d.versions.webviewBuiltAt})`
        : '';
      lines.push(`  - Webview bundle: ${webviewId}${built}`);
      if (buildId && buildId !== 'dev' && webviewId !== buildId) {
        lines.push(
          '  - ⚠️ The extension host and the webview were built from DIFFERENT source — this install is not one artifact, so a fix present in one half may be absent from the other. Reinstall the packaged extension before trusting either version above.',
        );
      }
    }
    if (d.versions.posixShell) lines.push(`  - ${d.versions.posixShell}`);
  }
  lines.push(`- Chat: ${d.chatTitle?.trim() ? `"${d.chatTitle.trim()}"` : 'Untitled'}${d.chatId != null ? ` (#${d.chatId})` : ''}${d.chatVisibility ? ` · ${d.chatVisibility}` : ''}`);
  // Directly under the chat line, because it qualifies everything below it: the same
  // trace reads as a healthy answer in `chat` and as an unfinished execution in `work`.
  if (d.mode) lines.push(`- Mode: ${d.mode}`);
  lines.push(`- Chat's project: ${fmtProject(d.projectId, d.projectName)}`);
  // ALWAYS printed, even when it matches (or is absent). Printing it only on a mismatch
  // is what made "nothing selected" and "selected but unadopted" indistinguishable.
  lines.push(
    `- Panel's selected project: ${fmtProject(d.selectedProjectId, d.selectedProjectName)}`
      + (d.selectedProjectId != null && d.selectedProjectId === d.projectId ? " (same as the chat's)" : ''),
  );
  lines.push(`- Tenant: ${d.tenantId != null ? `#${d.tenantId}` : 'unknown'} · User: ${d.userId ?? 'unknown'}`);

  // Account: plan, billing, quota and model entitlement. Rendered BEFORE the Evermind
  // block because it explains a whole class of "the model is dumb / it stopped
  // answering" reports that have nothing to do with wiring — a free, card-less tenant
  // out of tokens looks exactly like a broken install until these numbers are stated.
  const acct = d.account;
  if (acct) {
    lines.push(
      `- Plan: ${acct.plan ?? 'unknown'}`
        + ` · billing ${acct.billingStatus ?? 'none'}${acct.billingStatus === 'none' || acct.billingStatus == null ? ' (no payment method on file)' : ''}`
        + `${acct.canUsePremiumModels != null ? ` · premium models ${acct.canUsePremiumModels ? 'entitled' : 'NOT entitled'}` : ''}`
        // The surface a cloud run gets is a plan decision, so it belongs on the plan line
        // rather than being left for the reader to infer from the executors below.
        + `${acct.containerRuntime != null ? ` · container runtime ${acct.containerRuntime ? 'entitled (cloud runs get a real shell + clone)' : 'NOT entitled (cloud runs are routed to the shell-less durable surface)'}` : ''}`,
    );
    lines.push(
      `- Model: ${acct.model ?? 'auto (gateway routes per turn)'}`
        + `${acct.modelFunding ? ` · funded by ${acct.modelFunding}` : ''}`
        + `${acct.planModelCount != null ? ` · ${acct.planModelCount} models in plan pool` : ''}`
        + ` · BYO accounts: ${acct.byoProviders?.length ? acct.byoProviders.join(', ') : 'none'}`,
    );
    const meters = acct.meters ?? [];
    if (meters.length) {
      lines.push(`- Usage this period${acct.periodStart ? ` (since ${acct.periodStart}` : ''}${acct.resetsAt ? `${acct.periodStart ? ', ' : ' ('}resets ${acct.resetsAt})` : acct.periodStart ? ')' : ''}:`);
      for (const m of meters) lines.push(`  - ${fmtMeter(m)}`);
    } else {
      lines.push('- Usage this period: not available (consumption snapshot unavailable)');
    }
    if (acct.extensionVersion || acct.baseUrl) {
      lines.push(`- Client: ${acct.extensionVersion ? `v${acct.extensionVersion}` : 'unknown version'}${acct.baseUrl ? ` → ${acct.baseUrl}` : ''}`);
    }
  } else {
    lines.push('- Plan / usage: not gathered (account snapshot unavailable — signed out, or the consumption endpoint failed)');
  }

  // Tool availability — the difference between "the model chose not to act" and
  // "the model COULD not act". A zero here explains any number of turns that end
  // in "I don't have that data".
  const tools = d.tools;
  if (tools) {
    // REGISTERED vs ADVERTISED are different numbers and conflating them misreads
    // the fix: the whole catalog stays registered, but only a relevance-selected
    // subset is sent per turn (~300 definitions is past the point where most
    // providers reliably emit any tool call).
    //
    // This used to report the CEILING (`up to 64 advertised`) computed from the
    // registry size alone, while the Diagnostics block directly below reported the
    // MEASURED range off the same run's trace — one report, two answers to one
    // question, and the ceiling was the answer that could never be wrong-looking
    // enough to investigate. It now states what was actually sent, and says so
    // plainly when nothing has been measured yet rather than inventing a bound.
    lines.push(
      `- Tools available to the model: ${tools.count} registered`
        + fmtAdvertised(tools)
        + `${tools.loading ? ' (catalog still loading)' : ''}`
        + `${tools.error ? ` · catalog error: ${tools.error}` : ''}`,
    );
  } else {
    // NEVER omit this line. A silently absent tool count is indistinguishable from a
    // healthy one, and that is precisely how a surface that forgot to gather it went
    // unnoticed: the VSIX report read clean while the model had no tools to call.
    lines.push('- Tools available to the model: not gathered (this surface did not report its tool registry — a zero here is invisible, so treat any "announced a tool call and stopped" turn as unexplained)');
  }

  const ev = d.evermind;
  if (ev) {
    lines.push(
      `- Evermind (chat's project): v${ev.version} · ${ev.mode}`
        + `${ev.inferenceEnabled != null ? ` · inference ${ev.inferenceEnabled ? 'on' : 'off'}` : ''}`
        + ` · teacher ${ev.teacherModel ? ev.teacherModel : 'none'}`
        + `${ev.contributions != null ? ` · Learned ${ev.contributions}` : ''}`
        + `${ev.pending != null ? ` · Queued ${ev.pending}` : ''}`
        + ` · Last learned ${ev.lastLearnedAt ? ev.lastLearnedAt : 'never'}`,
    );
  } else {
    lines.push(`- Evermind (chat's project): not resolved (no project, or head unavailable)`);
  }

  if (d.lastLearn) {
    lines.push(
      `- Last turn learn gate: learned=${d.lastLearn.learned}`
        + ` · reported v${d.lastLearn.version}`
        + `${d.lastLearn.reason ? ` · reason=${d.lastLearn.reason}` : ''}`,
    );
  } else {
    lines.push('- Last turn learn gate: unknown (no assistant turn carried a learn outcome)');
  }

  // NAME first, ref in brackets. The ref still has to be here — it is what
  // `chats.dispatch_agent` takes and what an execution row records — but a report whose
  // roster line is three uuids cannot tell its reader who is on the work, which was the
  // whole reason to print the line.
  const agents = d.agents ?? [];
  lines.push(
    `- Agents in chat (${agents.length})`
      + (agents.length
        ? ': ' + agents.map((a) => {
            const name = a.name?.trim();
            const kind = a.builtinKind ? `, built-in ${a.builtinKind}` : '';
            return name && name !== a.agentRef
              ? `${name} [${a.agentRef}] (${a.role}${kind})`
              : `${a.agentRef} (${a.role}${kind})`;
          }).join(', ')
        : ''),
  );

  const tickets = d.tickets ?? [];
  if (tickets.length) {
    lines.push(`- Linked tickets (${tickets.length}):`);
    for (const tk of tickets) {
      lines.push(`  - ${tk.kind} #${tk.ref}${tk.label ? ` "${tk.label}"` : ''}${tk.linkType || tk.status ? ` [${[tk.linkType, tk.status].filter(Boolean).join(', ')}]` : ''}`);
    }
  } else {
    lines.push('- Linked tickets (0)');
  }

  lines.push(...runHistoryLines(d.runs));

  const signals = diagnosticsSignals(d);
  if (signals.length) {
    lines.push('', '### Signals');
    for (const s of signals) lines.push(`- ${s}`);
  }
  return lines;
}
